UPDATE growth_goals
   SET metric_type = #{goal.metricType},
       target_value = #{goal.targetValue},
       unit = #{goal.unit},
       period_start = #{goal.periodStart},
       period_end = #{goal.periodEnd},
       status = #{goal.status}
 WHERE id = #{goal.id}
   AND streamer_id = #{goal.streamerId}
